import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

const html=fs.readFileSync(new URL('../arcade.html',import.meta.url),'utf8');
const script=[...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)][0][1];
function fixture({storageFails=false}={}) {
 const elements=new Map();
 const context2d=new Proxy({}, {get:(_,key)=>()=>{}});
 class Element {
  constructor(id){this.id=id;this.tagName='BUTTON';this.textContent='';this.style={};this.dataset={};this.hidden=false;this.width=160;this.height=240;this.events={};this.classList={add(){},remove(){}};}
  getContext(){return context2d;}
  addEventListener(name,fn){(this.events[name]??=[]).push(fn);}
  emit(name,properties={}){const event={target:this,preventDefault(){},...properties};for(const fn of this.events[name]||[])fn(event);}
  blur(){document.activeElement=null;}
  setPointerCapture(){}
 }
 const buttons=['left','right','rotate','ccw','down','hold','drop'].map(action=>{const e=new Element(action);e.dataset.action=action;return e;});
 const document=new Element('document');document.tagName='BODY';document.getElementById=id=>{if(!elements.has(id))elements.set(id,new Element(id));return elements.get(id);};document.querySelectorAll=()=>buttons;document.hidden=false;document.activeElement=null;
 const window=new Element('window');const saved=new Map();let frame;
 const sandbox={document,window,HTMLElement:Element,performance:{now:()=>0},requestAnimationFrame:fn=>{frame=fn;},setTimeout:()=>1,clearTimeout(){},localStorage:{getItem(k){if(storageFails)throw Error('blocked');return saved.get(k);},setItem(k,v){if(storageFails)throw Error('blocked');saved.set(k,v);}}};
 vm.createContext(sandbox);vm.runInContext(script,sandbox);
 return {run:code=>vm.runInContext(code,sandbox),get:id=>document.getElementById(id),click(id){const el=this.get(id);document.activeElement=el;el.emit('click');},key(code,repeat=false){document.emit('keydown',{code,repeat,target:document.activeElement||document});},document,window,buttons,frame:time=>frame(time),saved};
}

test('standalone resources and no remote dependencies',()=>{
 assert.doesNotMatch(html,/<(?:script|link|img|iframe)\b[^>]*(?:src|href)\s*=/i);
 assert.doesNotMatch(html,/@import|url\(\s*['"]?https?:|\bfetch\s*\(/i);
});
test('seven-bag generation supplies every shape once per bag',()=>{
 const f=fixture();assert.equal(f.run(`(()=>{const g=new MoonGame(()=>.42),types=[];for(let i=0;i<70;i++){types.push(g.active.type);g.spawn();}return Array.from({length:10},(_,i)=>new Set(types.slice(i*7,i*7+7)).size).every(n=>n===7);})()`),true);
});
test('movement respects both walls, floor and occupied cells; rotation preserves cells',()=>{
 const f=fixture();assert.equal(f.run(`(()=>{const g=new MoonGame();g.active=g.piece('T');g.active.y=4;for(let i=0;i<30;i++)g.move(-1);if(g.move(-1))return false;for(let i=0;i<30;i++)g.move(1);if(g.move(1))return false;const count=()=>g.active.matrix.flat().filter(Boolean).length;for(let i=0;i<4;i++){if(!g.rotate()||count()!==4)return false;}g.active=g.piece('O');g.active.y=18;if(g.move(0,1))return false;g.active.y=4;g.board[6][4]='Z';return !g.move(0,1);})()`),true);
});
test('ghost and hard drop agree; hard drop scores and locks four cells',()=>{
 const f=fixture();assert.equal(f.run(`(()=>{const g=new MoonGame();g.active=g.piece('O');const y=g.ghostY(),distance=y-g.active.y;g.drop();return y===18&&g.score===distance*2&&g.board.flat().filter(Boolean).length===4&&g.board[19][4]==='O'&&!g.over;})()`),true);
});
test('one through four simultaneous lines score, compact and update level',()=>{
 const f=fixture();for(let n=1;n<=4;n++){
  assert.equal(f.run(`(()=>{const g=new MoonGame();g.active={type:'I',matrix:[[1],[1],[1],[1]],x:4,y:16};for(let y=20-${n};y<20;y++)g.board[y]=Array.from({length:10},(_,x)=>x===4?null:'J');g.lock();return g.lastClear===${n}&&g.lines===${n}&&g.score===${[0,100,300,500,800][n]}&&g.board.length===20&&g.board.flat().filter(Boolean).length===${4-n};})()`),true);
 }
 assert.equal(f.run(`(()=>{const g=new MoonGame();g.lines=9;g.board[19]=Array(10).fill('J');g.board[19][4]=null;g.active={type:'I',matrix:[[1]],x:4,y:19};g.lock();return g.level===2&&g.lines===10&&g.score===100;})()`),true);
});
test('hold can be used once per piece, then swaps without consuming queue',()=>{
 const f=fixture();assert.equal(f.run(`(()=>{const g=new MoonGame(),first=g.active.type,next=g.queue[0];if(!g.hold()||g.held!==first||g.active.type!==next||g.hold())return false;g.drop();const queue=g.queue.join(),current=g.active.type;return g.hold()&&g.active.type===first&&g.held===current&&g.queue.join()===queue&&g.active.y===-1;})()`),true);
});
test('spawn collision and above-ceiling lock end game; reset clears everything',()=>{
 const f=fixture();assert.equal(f.run(`(()=>{const g=new MoonGame();g.board[0].fill('Z');g.spawn('O');if(!g.over)return false;g.reset();g.active=g.piece('O');g.lock();if(!g.over)return false;g.reset();return !g.over&&g.score===0&&g.lines===0&&!g.held&&!g.holdUsed&&g.board.flat().every(v=>v===null);})()`),true);
});
test('launch releases focus, keyboard drop works, pause freezes and resumes simulation',()=>{
 const f=fixture();f.click('primary');assert.equal(f.document.activeElement,null);assert.equal(f.run('mode'),'playing');f.key('Space');assert.ok(f.run('game.score')>0);assert.equal(f.run('game.board.flat().filter(Boolean).length'),4);
 f.key('KeyP');assert.equal(f.run('mode'),'paused');const before=f.run('JSON.stringify(game)');f.key('ArrowLeft');for(let i=1;i<40;i++)f.frame(i*100);assert.equal(f.run('JSON.stringify(game)'),before);f.key('KeyP');assert.equal(f.run('mode'),'playing');const y=f.run('game.active.y');for(let i=40;i<50;i++)f.frame(i*100);assert.ok(f.run('game.active.y')>y);
});
test('touch movement, rotation, hold and drop use the same live engine',()=>{
 const f=fixture();f.click('primary');const touch=action=>f.buttons.find(b=>b.dataset.action===action).emit('pointerdown',{pointerId:1});const x=f.run('game.active.x');touch('left');assert.equal(f.run('game.active.x'),x-1);touch('right');assert.equal(f.run('game.active.x'),x);touch('rotate');touch('ccw');touch('hold');assert.equal(f.run('game.holdUsed'),true);touch('down');touch('drop');assert.equal(f.run('game.board.flat().filter(Boolean).length'),4);
});
test('restart requires confirmation; cancel preserves game; blur auto-pauses',()=>{
 const f=fixture();f.click('primary');f.key('Space');const score=f.run('game.score');f.click('restart');assert.equal(f.run('mode'),'confirm');f.click('restart');assert.equal(f.run('mode'),'paused');assert.equal(f.run('game.score'),score);f.click('primary');f.window.emit('blur');assert.equal(f.run('mode'),'paused');f.click('restart');f.click('primary');assert.equal(f.run('mode'),'playing');assert.equal(f.run('game.score'),0);assert.equal(f.get('restart').textContent,'↺ Restart');
});
test('game over shows final score, saves best, replays; blocked storage is harmless',()=>{
 for(const storageFails of [false,true]){const f=fixture({storageFails});f.click('primary');f.run('game.score=1234;game.over=true;finish();');assert.equal(f.run('mode'),'over');assert.equal(f.get('overlay').hidden,false);assert.match(f.get('overlayText').textContent,/1,234/);assert.equal(f.get('best').textContent,'1,234');if(!storageFails)assert.equal(f.saved.get('moonstack.best'),'1234');f.click('primary');assert.equal(f.run('game.over'),false);assert.equal(f.run('game.score'),0);}
});

